for r0,c0,n,flip_r,flip_c in [(5,20,2,False,True),(19,4,4,True,False),(20,20,2,True,True)]:
 s=n//2
 for r in range(3,7):
  for c in range(4,9):
   color=grid_alt[r][c]
   if color in (4,2,1): continue
